files.content:
:root {
  --bg: #1b1b2f;
  --card: #2e2e4a;
  --accent: #7f5af0;
  --text: #fffffe;
  --muted: #a7a9be;
  --border: 4px solid #0f0f1a;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
  background-image: linear-gradient(45deg, #22223b 25%, transparent 25%),
                    linear-gradient(-45deg, #22223b 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, #22223b 75%),
                    linear-gradient(-45deg, transparent 75%, #22223b 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
}

.card {
  background: var(--card);
  border: var(--border);
  border-radius: 12px;
  padding: 32px 24px;
  width: min(100%, 420px);
  text-align: center;
  box-shadow: 8px 8px 0 #0f0f1a;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 16px;
}

.count {
  display: block;
  font-size: clamp(3rem, 15vw, 5rem);
  font-weight: 800;
  line-height: 1.1;
  color: var(--accent);
  margin: 8px 0 24px;
  font-variant-numeric: tabular-nums;
  text-shadow: 3px 3px 0 #0f0f1a;
  word-break: break-all;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font: inherit;
  font-weight: 700;
  font-size: 1.25rem;
  min-width: 64px;
  min-height: 56px;
  padding: 8px 16px;
  cursor: pointer;
  color: var(--text);
  background: var(--accent);
  border: var(--border);
  border-radius: 8px;
  box-shadow: 4px 4px 0 #0f0f1a;
  transition: transform 0.08s ease, box-shadow 0.08s ease, background 0.15s ease;
}

.btn:hover {
  background: #9b7bff;
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0 #0f0f1a;
}

.btn:focus-visible {
  outline: 3px solid #ffd166;
  outline-offset: 3px;
}

.btn:active {
  transform: translate(3px, 3px);
  box-shadow: 1px 1px 0 #0f0f1a;
}

.btn-reset {
  background: #2cb67d;
  font-size: 1rem;
}

.btn-reset:hover {
  background: #3ddc97;
}

.hint {
  margin-top: 24px;
  font-size: 0.875rem;
  color: var(--muted);
  line-height: 1.5;
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  .btn { flex: 1 1 0; min-width: 0; padding: 8px 8px; }
  .btn-reset { font-size: 0.9rem; }
}

const countEl = document.getElementById('count');
const increaseBtn = document.getElementById('increase');
const decreaseBtn = document.getElementById('decrease');
const resetBtn = document.getElementById('reset');

let count = 0;

function updateDisplay() {
  countEl.textContent = count;
}

function increase() {
  count += 1;
  updateDisplay();
}

function decrease() {
  count -= 1;
  updateDisplay();
}

function reset() {
  count = 0;
  updateDisplay();
}

increaseBtn.addEventListener('click', increase);
decreaseBtn.addEventListener('click', decrease);
resetBtn.addEventListener('click', reset);

document.addEventListener('keydown', (event) => {
  if (event.target.tagName === 'BUTTON') return;
  if (event.key === '+' || event.key === '=') {
    event.preventDefault();
    increase();
  } else if (event.key === '-' || event.key === '_') {
    event.preventDefault();
    decrease();
  } else if (event.key === '0') {
    event.preventDefault();
    reset();
  }
});

updateDisplay();
